INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('cf93cb7f-16f9-59fd-9cf5-d79b4b2b6e28', '8334b783-acf4-5cb7-ae98-c34671f363f4', '{"en": "What are the angels who record our deeds called in the Quran?", "bn": "আমাদের আমল লেখেন যে ফেরেশতারা, কুরআনে তাঁদের কী বলা হয়েছে?"}', '{"en": "\"Noble, recording; they know what you do.\"", "bn": "\"সম্মানিত লেখকগণ; তারা জানে তোমরা যা করো।\""}', 'Quran 82:10–12', 8) ON CONFLICT (id) DO NOTHING;
