INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('3022c4de-a101-52c8-9154-c8dba04e3150', '0b9d657f-8e10-5659-8d8f-3cb02c1f44fb', '{"en": "How many names does the hadith mention, whoever learns them enters Paradise?", "bn": "যে হাদিসে বলা হয়েছে এগুলো আয়ত্ত করলে জান্নাত, সেখানে কয়টি নামের কথা আছে?"}', '{"en": "\"Allah has ninety-nine names; whoever enumerates them enters Paradise.\"", "bn": "\"আল্লাহর নিরানব্বইটি নাম আছে; যে এগুলো আয়ত্ত করবে সে জান্নাতে যাবে।\""}', 'Sahih al-Bukhari 2736', 9) ON CONFLICT (id) DO NOTHING;
