INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('8b48c309-06d1-5306-817f-5eda33b1385c', 'f7205f99-7fd9-59b5-8b0e-27df2b43b0a8', '{"en": "When can Umrah be performed?", "bn": "উমরা কখন করা যায়?"}', '{"en": "Umrah has no fixed season; Umrah in Ramadan has a special reward.", "bn": "উমরার নির্দিষ্ট সময় নেই; রমজানের উমরার বিশেষ সওয়াব আছে।"}', 'Sahih al-Bukhari 1782', 8) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('a9fcd71a-f78d-52b9-ac5c-1373a0dfaf04', '8b48c309-06d1-5306-817f-5eda33b1385c', '{"en": "Only in Ramadan", "bn": "শুধু রমজানে"}', false, 1), ('9a16bdcf-e07c-525a-b1d4-741df8ab98c0', '8b48c309-06d1-5306-817f-5eda33b1385c', '{"en": "Only in Dhul Hijjah", "bn": "শুধু জিলহজে"}', false, 2), ('ce1100cc-1e85-5e12-b5cf-7290b2fc243c', '8b48c309-06d1-5306-817f-5eda33b1385c', '{"en": "Any time of the year", "bn": "বছরের যেকোনো সময়"}', true, 3), ('1d55ed13-0cd9-5f85-b1bd-97807dc471b9', '8b48c309-06d1-5306-817f-5eda33b1385c', '{"en": "Only on Fridays", "bn": "শুধু শুক্রবার"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('c0094fe8-57c2-5c08-b870-fe35c01d5660', 'f7205f99-7fd9-59b5-8b0e-27df2b43b0a8', '{"en": "The Eid al-Adha sacrifice recalls the story of…?", "bn": "ঈদুল আযহার কোরবানি কার ঘটনা স্মরণ করায়?"}', '{"en": "Ibrahim’s readiness to sacrifice his son, ransomed with a great sacrifice.", "bn": "ইবরাহিম (আ.)-এর পুত্রকে কোরবানির প্রস্তুতি, যার বিনিময়ে মহান কোরবানি দেওয়া হয়।"}', 'Quran 37:102–107', 9) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('73cc8b88-76bb-5cd3-b90d-9723ca936ff0', 'c0094fe8-57c2-5c08-b870-fe35c01d5660', '{"en": "Nuh and the Ark", "bn": "নুহ ও কিশতি"}', false, 1), ('cb229ee3-cd3e-58c0-a5a1-78956985b67f', 'c0094fe8-57c2-5c08-b870-fe35c01d5660', '{"en": "Ibrahim and his son", "bn": "ইবরাহিম ও তাঁর পুত্র"}', true, 2), ('d27336c9-85d0-505c-a536-e42286c1bf90', 'c0094fe8-57c2-5c08-b870-fe35c01d5660', '{"en": "Musa and Pharaoh", "bn": "মুসা ও ফেরাউন"}', false, 3), ('b4dcbe43-539a-58e5-a67f-137327711a5a', 'c0094fe8-57c2-5c08-b870-fe35c01d5660', '{"en": "Yunus and the fish", "bn": "ইউনুস ও মাছ"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('861df494-c5aa-5500-b0f6-8437869deef1', 'f7205f99-7fd9-59b5-8b0e-27df2b43b0a8', '{"en": "The sacred state entered for Hajj or Umrah is…?", "bn": "হজ বা উমরার জন্য যে পবিত্র অবস্থায় প্রবেশ করা হয় তা হলো…?"}', '{"en": "Ihram begins at the miqat with the intention and talbiyah.", "bn": "মিকাতে নিয়ত ও তালবিয়ার মাধ্যমে ইহরাম শুরু হয়।"}', NULL, 10) ON CONFLICT (id) DO NOTHING;
