INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('e6e5e6f9-6369-5c62-89d8-8dd1e95c539e', '34e01e92-7c25-540d-9448-1e8f62943485', '{"en": "Who was called \"Dhun-Nurayn\" (owner of two lights)?", "bn": "কাকে \"যুন-নুরাইন\" (দুই আলোর অধিকারী) বলা হয়?"}', '{"en": "‘Uthman married two daughters of the Prophet ﷺ, Ruqayyah and then Umm Kulthum.", "bn": "উসমান (রা.) নবীজির ﷺ দুই কন্যা রুকাইয়া ও উম্মে কুলসুমকে বিয়ে করেছিলেন।"}', NULL, 3) ON CONFLICT (id) DO NOTHING;
