INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('3588c9ce-3834-5a59-8a99-2a29e4c2b418', '34e01e92-7c25-540d-9448-1e8f62943485', '{"en": "Which companion narrated the most hadith?", "bn": "কোন সাহাবি সবচেয়ে বেশি হাদিস বর্ণনা করেছেন?"}', '{"en": "Abu Hurayrah stayed close to the Prophet ﷺ to learn and memorise.", "bn": "আবু হুরায়রা (রা.) শেখা ও মুখস্থের জন্য নবীজির ﷺ কাছে থাকতেন।"}', 'Sahih al-Bukhari 118', 6) ON CONFLICT (id) DO NOTHING;
