INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('afcf71b2-b9fb-57af-844a-23b96f742600', 'b1a2a778-e5cb-5e96-8a84-41b67ba12dba', '{"en": "Who was the first person to accept Islam?", "bn": "সর্বপ্রথম কে ইসলাম গ্রহণ করেন?"}', '{"en": "Khadijah believed in him first and comforted him after the first revelation.", "bn": "খাদিজা (রা.) সবার আগে ঈমান আনেন এবং প্রথম ওহির পর নবীজিকে সান্ত্বনা দেন।"}', 'Sahih al-Bukhari 3', 1) ON CONFLICT (id) DO NOTHING;
