INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('a8161c81-5246-5c7e-a7c0-10afcd691cbd', 'b1a2a778-e5cb-5e96-8a84-41b67ba12dba', '{"en": "Whose wife believed in Allah and is praised in the Quran?", "bn": "কার স্ত্রী আল্লাহর প্রতি ঈমান আনেন এবং কুরআনে প্রশংসিত?"}', '{"en": "\"…the wife of Pharaoh, when she said: My Lord, build for me a house near You in Paradise.\"", "bn": "\"…ফেরাউনের স্ত্রী, যখন সে বলল: হে আমার রব, আপনার কাছে জান্নাতে আমার জন্য একটি ঘর বানিয়ে দিন।\""}', 'Quran 66:11', 4) ON CONFLICT (id) DO NOTHING;
