INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('2447bbe7-21ab-5c3e-89a0-4a1ede5de4b4', 'b1a2a778-e5cb-5e96-8a84-41b67ba12dba', '{"en": "Musa’s mother was inspired to put him in a box in…?", "bn": "মুসার মা কোথায় তাঁকে বাক্সে রাখার ইলহাম পেয়েছিলেন?"}', '{"en": "\"…cast him into the river and do not fear.\"", "bn": "\"…তাকে নদীতে ফেলে দাও এবং ভয় কোরো না।\""}', 'Quran 28:7', 9) ON CONFLICT (id) DO NOTHING;
