INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('fe8fb25a-b8fd-58b4-a6e2-749c216fa99c', 'b1a2a778-e5cb-5e96-8a84-41b67ba12dba', '{"en": "Who are called \"Mothers of the Believers\"?", "bn": "\"উম্মাহাতুল মুমিনিন\" (মুমিনদের মা) কারা?"}', '{"en": "\"…and his wives are their mothers.\"", "bn": "\"…আর তাঁর স্ত্রীগণ তাদের মা।\""}', 'Quran 33:6', 10) ON CONFLICT (id) DO NOTHING;
