INSERT INTO is_quizzes (id, title, topic, difficulty, time_limit_seconds, points_per_question, review_status, sort_order) VALUES ('f371ac12-10bc-5740-95f5-46dde45cdfff', '{"en": "Stories of the Quran", "bn": "কুরআনের ঘটনাবলি"}', 'quran', 'medium', NULL, 10, 'in_review', 13) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('311d5669-f848-51c7-993f-e7a64ba26764', 'f371ac12-10bc-5740-95f5-46dde45cdfff', '{"en": "The young men who slept in the cave are in which surah?", "bn": "গুহায় ঘুমন্ত যুবকদের ঘটনা কোন সূরায়?"}', '{"en": "Al-Kahf (\"the Cave\") tells of the People of the Cave.", "bn": "আল-কাহফ (\"গুহা\") সূরায় আসহাবে কাহফের ঘটনা।"}', 'Quran 18:9–26', 1) ON CONFLICT (id) DO NOTHING;
