INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('359f139a-3dfe-50a1-81af-15749cee66f7', 'f371ac12-10bc-5740-95f5-46dde45cdfff', '{"en": "Which queen visited Sulayman?", "bn": "কোন রানি সুলাইমান (আ.)-এর কাছে এসেছিলেন?"}', '{"en": "The story of the Queen of Saba is in surah an-Naml.", "bn": "সাবার রানির ঘটনা সূরা আন-নামলে।"}', 'Quran 27:22–44', 3) ON CONFLICT (id) DO NOTHING;
