INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('60406658-89ff-552c-bd95-07a2a56dc359', 'f371ac12-10bc-5740-95f5-46dde45cdfff', '{"en": "The people of ‘Ad, destroyed by a furious wind, were sent which prophet?", "bn": "প্রচণ্ড ঝড়ে ধ্বংস হওয়া আদ জাতির কাছে কোন নবী প্রেরিত হন?"}', '{"en": "\"And as for ‘Ad, they were destroyed by a screaming, violent wind.\"", "bn": "\"আর আদ জাতি, তাদের ধ্বংস করা হয়েছিল প্রচণ্ড ঝঞ্ঝাবায়ু দিয়ে।\""}', 'Quran 69:6; 7:65', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('1c58ab20-9331-50b8-94ea-d028c3b2002f', '60406658-89ff-552c-bd95-07a2a56dc359', '{"en": "Hud", "bn": "হুদ"}', true, 1), ('e94e6e55-a9b0-502b-b848-67952cf8f20b', '60406658-89ff-552c-bd95-07a2a56dc359', '{"en": "Salih", "bn": "সালিহ"}', false, 2), ('b8ed487e-dc24-5019-be5f-bf3143c270c6', '60406658-89ff-552c-bd95-07a2a56dc359', '{"en": "Lut", "bn": "লুত"}', false, 3), ('4f4a3768-980f-5459-aafa-fa71fb2cbbcf', '60406658-89ff-552c-bd95-07a2a56dc359', '{"en": "Shu‘ayb", "bn": "শুআইব"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('b2595749-de2f-55d5-9217-051d0524f08b', 'f371ac12-10bc-5740-95f5-46dde45cdfff', '{"en": "A she-camel was a sign for the people of which prophet?", "bn": "একটি উটনী কোন নবীর জাতির জন্য নিদর্শন ছিল?"}', '{"en": "The she-camel of Allah, sent to Thamud.", "bn": "সামুদ জাতির কাছে পাঠানো আল্লাহর উটনী।"}', 'Quran 7:73', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('58ecdc61-4722-596e-84f8-47ce16b116ec', 'b2595749-de2f-55d5-9217-051d0524f08b', '{"en": "Salih", "bn": "সালিহ"}', true, 1), ('f4bcc6c8-84f3-5c18-b9a6-f002d6b3ce5e', 'b2595749-de2f-55d5-9217-051d0524f08b', '{"en": "Hud", "bn": "হুদ"}', false, 2), ('33fe7e4a-66ac-5175-8226-d1758bbcbaa3', 'b2595749-de2f-55d5-9217-051d0524f08b', '{"en": "Ibrahim", "bn": "ইবরাহিম"}', false, 3), ('bb72ad0d-3d0c-5cce-a02b-bc58729138a2', 'b2595749-de2f-55d5-9217-051d0524f08b', '{"en": "Isa", "bn": "ঈসা"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('1a79f0ea-0d01-5bf2-86b4-59c0d31a929e', 'f371ac12-10bc-5740-95f5-46dde45cdfff', '{"en": "Musa travelled to learn from a righteous servant of Allah, known as…?", "bn": "মুসা (আ.) আল্লাহর এক নেক বান্দার কাছে শিখতে গিয়েছিলেন, যিনি পরিচিত…?"}', '{"en": "The story is in al-Kahf; the hadith names him al-Khidr.", "bn": "ঘটনাটি সূরা কাহফে; হাদিসে তাঁর নাম খিজির।"}', 'Quran 18:60–82; Sahih al-Bukhari 122', 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('95ec53ed-504a-5f33-8f63-80c187c9eba8', '1a79f0ea-0d01-5bf2-86b4-59c0d31a929e', '{"en": "Al-Khidr", "bn": "খিজির"}', true, 1), ('4e63c899-ad63-55cb-867d-c0b2d11609a2', '1a79f0ea-0d01-5bf2-86b4-59c0d31a929e', '{"en": "Luqman", "bn": "লুকমান"}', false, 2), ('594ac695-4b31-5ba9-8262-df3a7d2c8aaa', '1a79f0ea-0d01-5bf2-86b4-59c0d31a929e', '{"en": "Dhul-Kifl", "bn": "যুলকিফল"}', false, 3), ('1f1c2282-d949-55dd-abc2-2b14817f7660', '1a79f0ea-0d01-5bf2-86b4-59c0d31a929e', '{"en": "Idris", "bn": "ইদরিস"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('af5715eb-8c5e-58ee-b56b-68ecae769057', 'f371ac12-10bc-5740-95f5-46dde45cdfff', '{"en": "Which prophet was thrown into a fire that Allah made cool?", "bn": "কোন নবীকে আগুনে নিক্ষেপ করা হলে আল্লাহ তা শীতল করে দেন?"}', '{"en": "\"O fire, be coolness and safety upon Ibrahim.\"", "bn": "\"হে আগুন, ইবরাহিমের জন্য শীতল ও নিরাপদ হয়ে যাও।\""}', 'Quran 21:69', 7) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('ec57c274-556c-5d8b-9740-451dfe822085', 'af5715eb-8c5e-58ee-b56b-68ecae769057', '{"en": "Ibrahim", "bn": "ইবরাহিম"}', true, 1), ('323a2cd2-2f8f-5b42-a516-085348650031', 'af5715eb-8c5e-58ee-b56b-68ecae769057', '{"en": "Musa", "bn": "মুসা"}', false, 2), ('60c6cfb2-8ca1-5b59-a34b-5c24486de9f2', 'af5715eb-8c5e-58ee-b56b-68ecae769057', '{"en": "Yahya", "bn": "ইয়াহইয়া"}', false, 3), ('1463d662-1093-54e8-868b-f8053b9bce6c', 'af5715eb-8c5e-58ee-b56b-68ecae769057', '{"en": "Ayyub", "bn": "আইয়ুব"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('762ca207-cb6f-5805-9739-328346491e2f', 'f371ac12-10bc-5740-95f5-46dde45cdfff', '{"en": "Whose brothers threw him into a well?", "bn": "কার ভাইয়েরা তাঁকে কূপে ফেলে দিয়েছিল?"}', '{"en": "\"…and agreed to put him into the bottom of the well.\"", "bn": "\"…এবং তাকে কূপের তলদেশে ফেলার সিদ্ধান্ত নিল।\""}', 'Quran 12:15', 8) ON CONFLICT (id) DO NOTHING;
