INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('1b1737a8-9989-5a8c-9cac-3c51564fa005', '59be8b82-0605-56da-b297-472744af47a0', '{"en": "On which weekdays did the Prophet ﷺ like to fast?", "bn": "নবী ﷺ সপ্তাহের কোন দিনগুলোতে রোজা রাখতে পছন্দ করতেন?"}', '{"en": "\"Deeds are presented on Monday and Thursday, and I like my deeds presented while I am fasting.\"", "bn": "\"সোম ও বৃহস্পতিবার আমল পেশ করা হয়; আমি চাই রোজা অবস্থায় আমার আমল পেশ হোক।\""}', 'Jami‘ at-Tirmidhi 747', 8) ON CONFLICT (id) DO NOTHING;
