INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('6d9236ec-514c-5713-9f10-6e31d0dd356b', '1efc93ae-f25f-5793-9e63-369c5b89e008', '{"en": "How do Muslims greet each other?", "bn": "মুসলমানরা একে অপরকে কীভাবে সালাম দেয়?"}', '{"en": "\"Spread salam among yourselves.\"", "bn": "\"তোমরা পরস্পরের মাঝে সালামের প্রসার ঘটাও।\""}', 'Sahih Muslim 54', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('29b913e6-7d09-5a61-af52-b85d926830bd', '6d9236ec-514c-5713-9f10-6e31d0dd356b', '{"en": "As-salamu alaykum", "bn": "আসসালামু আলাইকুম"}', true, 1), ('4c4d3cb1-a30c-59ef-920d-828e826fb380', '6d9236ec-514c-5713-9f10-6e31d0dd356b', '{"en": "Good morning", "bn": "শুভ সকাল"}', false, 2), ('acd22f78-bbda-5662-a52d-aeead506afdd', '6d9236ec-514c-5713-9f10-6e31d0dd356b', '{"en": "Ma‘as-salamah", "bn": "মাআস সালামা"}', false, 3), ('9be8862e-68ab-5222-abfc-c3e3d3df92b3', '6d9236ec-514c-5713-9f10-6e31d0dd356b', '{"en": "Bismillah", "bn": "বিসমিল্লাহ"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('343fed00-8f95-524d-bc99-063cb4c87a05', '1efc93ae-f25f-5793-9e63-369c5b89e008', '{"en": "How do you reply to \"As-salamu alaykum\"?", "bn": "\"আসসালামু আলাইকুম\"-এর জবাব কী?"}', '{"en": "\"…greet with better than it or return it.\"", "bn": "\"…তার চেয়ে উত্তম সালাম দাও অথবা অন্তত তা ফিরিয়ে দাও।\""}', 'Quran 4:86', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('693f7d4d-2021-5c91-a0ae-9daaf1c9c436', '343fed00-8f95-524d-bc99-063cb4c87a05', '{"en": "Wa alaykum as-salam", "bn": "ওয়া আলাইকুমুস সালাম"}', true, 1), ('e040f318-c82b-5268-adc3-f73222d276a6', '343fed00-8f95-524d-bc99-063cb4c87a05', '{"en": "Alhamdulillah", "bn": "আলহামদুলিল্লাহ"}', false, 2), ('21521f68-7014-5664-adf9-5073e7379024', '343fed00-8f95-524d-bc99-063cb4c87a05', '{"en": "Insha’Allah", "bn": "ইনশাআল্লাহ"}', false, 3), ('cd8409c5-2edd-5a90-a04c-3e7409a71f4e', '343fed00-8f95-524d-bc99-063cb4c87a05', '{"en": "Ameen", "bn": "আমিন"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('b67d4e1d-e41f-5205-b9c8-a7e91d7d154a', '1efc93ae-f25f-5793-9e63-369c5b89e008', '{"en": "With which hand should we eat and drink?", "bn": "কোন হাতে খাওয়া-পান করা উচিত?"}', '{"en": "\"When one of you eats, let him eat with his right hand.\"", "bn": "\"তোমাদের কেউ খেলে যেন ডান হাতে খায়।\""}', 'Sahih Muslim 2020', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('0ea7ad6a-b9b3-5668-acd1-f9714427bf14', 'b67d4e1d-e41f-5205-b9c8-a7e91d7d154a', '{"en": "Right hand", "bn": "ডান হাতে"}', true, 1), ('36461484-7e5e-5142-9bda-360a6943e0cf', 'b67d4e1d-e41f-5205-b9c8-a7e91d7d154a', '{"en": "Left hand", "bn": "বাম হাতে"}', false, 2), ('2577660e-f2db-5232-9aa4-25fe0afcd2dd', 'b67d4e1d-e41f-5205-b9c8-a7e91d7d154a', '{"en": "Either", "bn": "যেকোনো হাতে"}', false, 3), ('a0d886d5-0b4f-5afb-98e6-9403846fb7c4', 'b67d4e1d-e41f-5205-b9c8-a7e91d7d154a', '{"en": "Both", "bn": "দুই হাতে"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('d340b555-5261-50b0-b40c-c7592d94c882', '1efc93ae-f25f-5793-9e63-369c5b89e008', '{"en": "What should you say after sneezing?", "bn": "হাঁচি দেওয়ার পর কী বলা উচিত?"}', '{"en": "The one who sneezes says \"Alhamdulillah\".", "bn": "যে হাঁচি দেয় সে বলবে \"আলহামদুলিল্লাহ\"।"}', 'Sahih al-Bukhari 6224', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('1b63294e-177d-5de1-8252-23641b251634', 'd340b555-5261-50b0-b40c-c7592d94c882', '{"en": "Alhamdulillah", "bn": "আলহামদুলিল্লাহ"}', true, 1), ('92274b4d-1d52-5eca-981d-98b909957b78', 'd340b555-5261-50b0-b40c-c7592d94c882', '{"en": "SubhanAllah", "bn": "সুবহানাল্লাহ"}', false, 2), ('f551c7f5-f09b-54c9-8581-3b8c82d1901f', 'd340b555-5261-50b0-b40c-c7592d94c882', '{"en": "Allahu Akbar", "bn": "আল্লাহু আকবার"}', false, 3), ('06cea6cf-e301-5d84-87b0-d69026961868', 'd340b555-5261-50b0-b40c-c7592d94c882', '{"en": "Astaghfirullah", "bn": "আস্তাগফিরুল্লাহ"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('5969405f-7eb9-5ce8-9f28-a0c5d41b3465', '1efc93ae-f25f-5793-9e63-369c5b89e008', '{"en": "What do you say to someone who sneezes and says Alhamdulillah?", "bn": "কেউ হাঁচি দিয়ে আলহামদুলিল্লাহ বললে তাকে কী বলবেন?"}', '{"en": "\"May Allah have mercy on you.\"", "bn": "\"আল্লাহ তোমার প্রতি রহম করুন।\""}', 'Sahih al-Bukhari 6224', 5) ON CONFLICT (id) DO NOTHING;
