INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('bab7ef2e-cb91-590d-b079-544cbc3db538', '1efc93ae-f25f-5793-9e63-369c5b89e008', '{"en": "Smiling at your brother is…?", "bn": "ভাইয়ের দিকে মুচকি হাসা হলো…?"}', '{"en": "\"Your smile in the face of your brother is charity.\"", "bn": "\"তোমার ভাইয়ের সামনে তোমার হাসি সদকা।\""}', 'Jami‘ at-Tirmidhi 1956', 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('03c2d016-9966-5429-8935-7d16c5bfdb38', 'bab7ef2e-cb91-590d-b079-544cbc3db538', '{"en": "A charity (sadaqah)", "bn": "সদকা"}', true, 1), ('760df1d8-09d6-5953-b400-6edf3353ce1c', 'bab7ef2e-cb91-590d-b079-544cbc3db538', '{"en": "Disliked", "bn": "অপছন্দনীয়"}', false, 2), ('ab815c9c-acc7-5891-bd19-77024e21b42a', 'bab7ef2e-cb91-590d-b079-544cbc3db538', '{"en": "Only for children", "bn": "শুধু শিশুদের জন্য"}', false, 3), ('2f3e8729-89e1-5793-b1e2-bcd06a28791a', 'bab7ef2e-cb91-590d-b079-544cbc3db538', '{"en": "Wasting time", "bn": "সময় নষ্ট"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('dd0c4977-b738-585a-8373-da12e99022a5', '1efc93ae-f25f-5793-9e63-369c5b89e008', '{"en": "Complete: \"None of you truly believes until he loves for his brother what he…\"", "bn": "পূর্ণ করুন: \"তোমাদের কেউ পূর্ণ মুমিন হবে না, যতক্ষণ না সে তার ভাইয়ের জন্য তা পছন্দ করে যা সে…\""}', '{"en": "Wanting good for others as for yourself is part of faith.", "bn": "নিজের মতো অন্যের জন্য কল্যাণ চাওয়া ঈমানের অংশ।"}', 'Sahih al-Bukhari 13', 7) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('75cdb3d4-7676-5081-a396-fbd5d7c0ad75', 'dd0c4977-b738-585a-8373-da12e99022a5', '{"en": "…loves for himself", "bn": "…নিজের জন্য পছন্দ করে"}', true, 1), ('d2be102d-7292-5a89-acd5-ccb5738903b8', 'dd0c4977-b738-585a-8373-da12e99022a5', '{"en": "…owns", "bn": "…মালিক"}', false, 2), ('016049d1-c523-5e97-8676-1ffafbe358ad', 'dd0c4977-b738-585a-8373-da12e99022a5', '{"en": "…fears", "bn": "…ভয় করে"}', false, 3), ('30e17952-b8a3-5602-b7d2-73c1ff748ae8', 'dd0c4977-b738-585a-8373-da12e99022a5', '{"en": "…eats", "bn": "…খায়"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('334bb973-1001-519b-bacb-eabcfbecd8d3', '1efc93ae-f25f-5793-9e63-369c5b89e008', '{"en": "Who are the best of you, according to the hadith?", "bn": "হাদিস অনুযায়ী তোমাদের মধ্যে শ্রেষ্ঠ কে?"}', '{"en": "\"The best of you are those who learn the Quran and teach it.\"", "bn": "\"তোমাদের মধ্যে সর্বোত্তম সে, যে কুরআন শেখে ও শেখায়।\""}', 'Sahih al-Bukhari 5027', 8) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('d24c44ba-aa83-546b-a2e1-213c2123ab88', '334bb973-1001-519b-bacb-eabcfbecd8d3', '{"en": "The richest", "bn": "সবচেয়ে ধনী"}', false, 1), ('63bdfeee-ce5b-5d4f-9df9-b45ad8d228e4', '334bb973-1001-519b-bacb-eabcfbecd8d3', '{"en": "Those who learn the Quran and teach it", "bn": "যে কুরআন শেখে ও শেখায়"}', true, 2), ('83cb855d-7b2b-515f-8e57-57ef317dc7bf', '334bb973-1001-519b-bacb-eabcfbecd8d3', '{"en": "The strongest", "bn": "সবচেয়ে শক্তিশালী"}', false, 3), ('30d48274-9965-55e0-8784-7656f4c70f1a', '334bb973-1001-519b-bacb-eabcfbecd8d3', '{"en": "The oldest", "bn": "সবচেয়ে বয়স্ক"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('15ec9be6-b2db-5d03-a42b-cf5adadbb5b8', '1efc93ae-f25f-5793-9e63-369c5b89e008', '{"en": "What should a Muslim say before starting something good?", "bn": "ভালো কাজ শুরুর আগে মুসলমান কী বলবে?"}', '{"en": "\"In the name of Allah\", as before eating, wudu and leaving home.", "bn": "\"আল্লাহর নামে\", যেমন খাওয়া, অজু ও ঘর থেকে বের হওয়ার আগে।"}', 'Sunan Abi Dawud 3767', 9) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('50be4cae-a046-501c-9b52-28718eae4570', '15ec9be6-b2db-5d03-a42b-cf5adadbb5b8', '{"en": "Bismillah", "bn": "বিসমিল্লাহ"}', true, 1), ('f67afda7-2666-5628-a97f-e2001331153a', '15ec9be6-b2db-5d03-a42b-cf5adadbb5b8', '{"en": "Ameen", "bn": "আমিন"}', false, 2), ('ff92fac5-72ee-5282-81f7-d6dcaeb3c0a3', '15ec9be6-b2db-5d03-a42b-cf5adadbb5b8', '{"en": "Wa alaykum", "bn": "ওয়া আলাইকুম"}', false, 3), ('98000c57-25c1-5361-bf57-ee54f0fea56b', '15ec9be6-b2db-5d03-a42b-cf5adadbb5b8', '{"en": "Ma‘as-salamah", "bn": "মাআস সালামা"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('5a8e7e47-49e6-55c4-b24d-47738c818de5', '1efc93ae-f25f-5793-9e63-369c5b89e008', '{"en": "Who has the greatest right to your good company?", "bn": "তোমার সদাচরণ পাওয়ার সবচেয়ে বেশি হকদার কে?"}', '{"en": "\"Your mother, then your mother, then your mother, then your father.\"", "bn": "\"তোমার মা, তারপর তোমার মা, তারপর তোমার মা, তারপর তোমার বাবা।\""}', 'Sahih al-Bukhari 5971', 10) ON CONFLICT (id) DO NOTHING;
