INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('dc5acbe8-a68d-5d87-9b63-b1023e4deab6', 'b90a93e5-faad-5cd9-9e6d-412ebea73dca', '{"en": "Which surah has Bismillah twice?", "bn": "কোন সূরায় বিসমিল্লাহ দুইবার আছে?"}', '{"en": "At its start and inside Sulayman’s letter: \"…it is in the name of Allah, the Most Merciful\".", "bn": "শুরুতে এবং সুলাইমানের চিঠিতে: \"…তা পরম দয়াময় আল্লাহর নামে\"।"}', 'Quran 27:30', 2) ON CONFLICT (id) DO NOTHING;
