INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('52082a42-8a33-5954-8a6b-8a20d8451c1a', '1c1d4678-7656-567e-8ff9-7b4dbd39b3f1', '{"en": "Which uncle protected him in Makkah?", "bn": "কোন চাচা মক্কায় তাঁকে রক্ষা করেছিলেন?"}', '{"en": "Abu Talib protected him until his death in the \"Year of Sorrow\".", "bn": "আবু তালিব \"দুঃখের বছরে\" মৃত্যু পর্যন্ত তাঁকে রক্ষা করেন।"}', NULL, 3) ON CONFLICT (id) DO NOTHING;
