INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('2e23e3f6-ef34-5469-a405-a5a5cc4d936e', '1c1d4678-7656-567e-8ff9-7b4dbd39b3f1', '{"en": "How old was he when the first revelation came?", "bn": "প্রথম ওহির সময় তাঁর বয়স কত ছিল?"}', '{"en": "Revelation began when he was forty.", "bn": "চল্লিশ বছর বয়সে ওহি শুরু হয়।"}', 'Sahih al-Bukhari 3851', 4) ON CONFLICT (id) DO NOTHING;
