INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('25e47dce-8965-5f2f-b75c-71692efad4bf', '291a98bb-29b8-5e2a-b8c3-94a408d4f06b', '{"en": "Which prophet was given the son Yahya in old age?", "bn": "কোন নবীকে বৃদ্ধ বয়সে পুত্র ইয়াহইয়া দেওয়া হয়?"}', '{"en": "\"O Zakariyya, We give you good news of a boy whose name is Yahya.\"", "bn": "\"হে যাকারিয়া, আমি তোমাকে এক পুত্রের সুসংবাদ দিচ্ছি, তার নাম ইয়াহইয়া।\""}', 'Quran 19:7', 3) ON CONFLICT (id) DO NOTHING;
