INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('7e32f9d5-b832-57b3-acd4-e8fb92a8585b', '291a98bb-29b8-5e2a-b8c3-94a408d4f06b', '{"en": "Which prophet’s people had their cities turned upside down?", "bn": "কোন নবীর জাতির জনপদ উল্টে দেওয়া হয়েছিল?"}', '{"en": "\"…We made the highest part of it its lowest.\"", "bn": "\"…আমি তার উপরিভাগকে নিচে করে দিলাম।\""}', 'Quran 11:82', 8) ON CONFLICT (id) DO NOTHING;
