INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('08a26ded-1841-5cef-aa71-4e8547e50417', '81aa5327-18cd-5fd1-aae9-12ee2288fceb', '{"en": "For whom is Zakat al-Fitr given?", "bn": "সদকাতুল ফিতর কার পক্ষ থেকে দিতে হয়?"}', '{"en": "\"…on the slave and the free, male and female, young and old of the Muslims.\"", "bn": "\"…মুসলমানদের দাস-স্বাধীন, নারী-পুরুষ, ছোট-বড় সবার ওপর।\""}', 'Sahih al-Bukhari 1503', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('1f0cb325-76de-5c31-8caf-d92b95ec0b3b', '08a26ded-1841-5cef-aa71-4e8547e50417', '{"en": "Only rich men", "bn": "শুধু ধনী পুরুষ"}', false, 1), ('3d3f945b-1bc7-55dd-99d9-6db51b928baf', '08a26ded-1841-5cef-aa71-4e8547e50417', '{"en": "Every Muslim, young and old", "bn": "ছোট-বড় প্রত্যেক মুসলমান"}', true, 2), ('3e8ea420-d232-54b8-982c-ca7146c76e3e', '08a26ded-1841-5cef-aa71-4e8547e50417', '{"en": "Only fasting adults", "bn": "শুধু রোজাদার প্রাপ্তবয়স্ক"}', false, 3), ('8ca1adcc-e42c-537c-a95e-9e2d4927ab2e', '08a26ded-1841-5cef-aa71-4e8547e50417', '{"en": "Only scholars", "bn": "শুধু আলেম"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('3671c1fd-dd0f-5c81-bcd9-ab48bee9c194', '81aa5327-18cd-5fd1-aae9-12ee2288fceb', '{"en": "Which ayah lists who may receive zakat?", "bn": "কোন আয়াতে যাকাতের হকদারদের তালিকা আছে?"}', '{"en": "At-Tawbah 9:60.", "bn": "আত-তাওবা ৯:৬০।"}', 'Quran 9:60', 2) ON CONFLICT (id) DO NOTHING;
