INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('6c6f24cc-7586-5254-999d-baa7c7178a23', 'a08574d0-8533-5a3a-bac9-948e078d147b', '{"en": "Masjid an-Nabawi (the Prophet’s Mosque) is in…?", "bn": "মসজিদে নববী কোথায়?"}', '{"en": "He ﷺ built it after the Hijrah.", "bn": "হিজরতের পর তিনি ﷺ এটি নির্মাণ করেন।"}', NULL, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('97a782b4-af77-581d-825a-08037158c6f3', '6c6f24cc-7586-5254-999d-baa7c7178a23', '{"en": "Madinah", "bn": "মদিনা"}', true, 1), ('3f54b9fc-3d4e-5141-8bbd-d267dbe4ef31', '6c6f24cc-7586-5254-999d-baa7c7178a23', '{"en": "Makkah", "bn": "মক্কা"}', false, 2), ('1ea8a727-033a-51bb-bb0f-bfd82c69722f', '6c6f24cc-7586-5254-999d-baa7c7178a23', '{"en": "Ta’if", "bn": "তায়েফ"}', false, 3), ('fd3943ce-9e5a-5c31-a408-51bb1d69be08', '6c6f24cc-7586-5254-999d-baa7c7178a23', '{"en": "Jeddah", "bn": "জেদ্দা"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('8464f475-1f56-59d3-8075-eb3ddb916cd9', 'a08574d0-8533-5a3a-bac9-948e078d147b', '{"en": "Which three mosques may one travel to for worship?", "bn": "ইবাদতের উদ্দেশ্যে কোন তিন মসজিদে সফর করা যায়?"}', '{"en": "\"Do not set out on a journey except to three mosques…\"", "bn": "\"তিনটি মসজিদ ছাড়া অন্য কোথাও (ইবাদতের উদ্দেশ্যে) সফর করো না…\""}', 'Sahih al-Bukhari 1189', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('75ea052a-a80b-5cf3-9d44-450c90f382ec', '8464f475-1f56-59d3-8075-eb3ddb916cd9', '{"en": "Al-Haram, an-Nabawi, al-Aqsa", "bn": "আল-হারাম, আন-নববী, আল-আকসা"}', true, 1), ('9f93c07b-d11d-5b3b-a82a-be7c8d9d91c9', '8464f475-1f56-59d3-8075-eb3ddb916cd9', '{"en": "Quba, al-Haram, Uhud", "bn": "কুবা, আল-হারাম, উহুদ"}', false, 2), ('ff4b7b9a-8abc-5345-81ec-f20c80a491de', '8464f475-1f56-59d3-8075-eb3ddb916cd9', '{"en": "Any three", "bn": "যেকোনো তিনটি"}', false, 3), ('ce46de66-b764-5516-b78e-ceda81ec2d6a', '8464f475-1f56-59d3-8075-eb3ddb916cd9', '{"en": "Only al-Haram", "bn": "শুধু আল-হারাম"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('5016fbdb-ade7-5355-81dc-9baf53a39f24', 'a08574d0-8533-5a3a-bac9-948e078d147b', '{"en": "Which was the first mosque the Prophet ﷺ built?", "bn": "নবী ﷺ নির্মিত প্রথম মসজিদ কোনটি?"}', '{"en": "Built at Quba on the way to Madinah, \"founded on taqwa\".", "bn": "মদিনার পথে কুবায় নির্মিত, \"তাকওয়ার ভিত্তিতে প্রতিষ্ঠিত\"।"}', 'Quran 9:108', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('d408acd0-4fc8-5010-b395-49e753f8a95e', '5016fbdb-ade7-5355-81dc-9baf53a39f24', '{"en": "Quba", "bn": "কুবা"}', true, 1), ('a35863b0-364e-5305-b9b6-8224958ab5c2', '5016fbdb-ade7-5355-81dc-9baf53a39f24', '{"en": "Al-Aqsa", "bn": "আল-আকসা"}', false, 2), ('cf9822bc-a305-515b-8cab-595fcb231264', '5016fbdb-ade7-5355-81dc-9baf53a39f24', '{"en": "Al-Haram", "bn": "আল-হারাম"}', false, 3), ('0470a803-b372-5b29-91fe-f9b82194585d', '5016fbdb-ade7-5355-81dc-9baf53a39f24', '{"en": "Al-Qiblatayn", "bn": "আল-কিবলাতাইন"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('6fdd771e-5977-5817-95cd-85b3e0d2e2dd', 'a08574d0-8533-5a3a-bac9-948e078d147b', '{"en": "The cave of Hira is on which mountain?", "bn": "হেরা গুহা কোন পাহাড়ে?"}', '{"en": "Jabal an-Nur, \"the Mountain of Light\", near Makkah.", "bn": "মক্কার কাছে জাবালে নূর, \"আলোর পাহাড়\"।"}', NULL, 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('38bb772f-cabc-5df5-b70a-6360d52a83e7', '6fdd771e-5977-5817-95cd-85b3e0d2e2dd', '{"en": "Jabal an-Nur", "bn": "জাবালে নূর"}', true, 1), ('9495e06b-2072-5829-85ac-a003a68353bd', '6fdd771e-5977-5817-95cd-85b3e0d2e2dd', '{"en": "Uhud", "bn": "উহুদ"}', false, 2), ('91395523-bdfe-5578-9163-a9a6c44baed5', '6fdd771e-5977-5817-95cd-85b3e0d2e2dd', '{"en": "Sinai", "bn": "সিনাই"}', false, 3), ('9c84e065-2f1a-52e5-9a02-79fe2e98fe35', '6fdd771e-5977-5817-95cd-85b3e0d2e2dd', '{"en": "Thawr", "bn": "সাওর"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('c56760c9-2178-5104-b773-d11457ef3187', 'a08574d0-8533-5a3a-bac9-948e078d147b', '{"en": "Where do pilgrims stand on 9 Dhul Hijjah?", "bn": "৯ জিলহজ হাজিরা কোথায় অবস্থান করেন?"}', '{"en": "The plain of Arafat.", "bn": "আরাফাতের ময়দান।"}', 'Quran 2:198', 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('3adcd2ec-6400-5ce7-943c-ec1db571451f', 'c56760c9-2178-5104-b773-d11457ef3187', '{"en": "Arafat", "bn": "আরাফাত"}', true, 1), ('c1dd0ab3-26c4-5fac-8f79-915c870d2b68', 'c56760c9-2178-5104-b773-d11457ef3187', '{"en": "Mina", "bn": "মিনা"}', false, 2), ('65017d04-3c99-5e89-a606-013f02b24840', 'c56760c9-2178-5104-b773-d11457ef3187', '{"en": "Madinah", "bn": "মদিনা"}', false, 3), ('4af81dae-d1ab-579b-9ae2-e800b9100f9c', 'c56760c9-2178-5104-b773-d11457ef3187', '{"en": "Quba", "bn": "কুবা"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('ee1c1325-ecbd-5f0c-b8ba-683e4260fe08', 'a08574d0-8533-5a3a-bac9-948e078d147b', '{"en": "What is the cemetery of Madinah called?", "bn": "মদিনার কবরস্থানের নাম কী?"}', '{"en": "Many companions are buried in al-Baqi‘.", "bn": "অনেক সাহাবি জান্নাতুল বাকিতে সমাহিত।"}', NULL, 7) ON CONFLICT (id) DO NOTHING;
