INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('d88fe167-d445-56ea-a9f7-d71306b4bcee', 'a08574d0-8533-5a3a-bac9-948e078d147b', '{"en": "Which mountain near Madinah gave its name to a battle?", "bn": "মদিনার কাছের কোন পাহাড়ের নামে একটি যুদ্ধের নাম?"}', '{"en": "\"Uhud is a mountain that loves us and we love it.\"", "bn": "\"উহুদ এমন পাহাড়, যা আমাদের ভালোবাসে এবং আমরাও তাকে ভালোবাসি।\""}', 'Sahih al-Bukhari 4084', 8) ON CONFLICT (id) DO NOTHING;
