INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('4b7b30d2-865e-5bfe-8fe7-dbcf8048ec2e', 'a08574d0-8533-5a3a-bac9-948e078d147b', '{"en": "A prayer in Masjid al-Haram is worth how many prayers elsewhere?", "bn": "মসজিদুল হারামে এক নামাজ অন্যত্র কত নামাজের সমান?"}', '{"en": "\"…a prayer in al-Masjid al-Haram is better than 100,000 prayers elsewhere.\"", "bn": "\"…মসজিদুল হারামে এক নামাজ অন্যত্র এক লাখ নামাজের চেয়ে উত্তম।\""}', 'Sunan Ibn Majah 1406', 10) ON CONFLICT (id) DO NOTHING;
