INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('96279e7c-8d8c-57d3-9dbf-358eba192faa', 'f13c3417-7533-5e57-81f4-85dd9bbd88b6', '{"en": "What is the best dhikr, according to the hadith?", "bn": "হাদিস অনুযায়ী সর্বোত্তম যিকির কোনটি?"}', '{"en": "\"The best dhikr is La ilaha illallah.\"", "bn": "\"সর্বোত্তম যিকির লা ইলাহা ইল্লাল্লাহ।\""}', 'Jami‘ at-Tirmidhi 3383', 1) ON CONFLICT (id) DO NOTHING;
