INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('cd2b657c-9181-5eec-9fea-769a6496adc5', 'f13c3417-7533-5e57-81f4-85dd9bbd88b6', '{"en": "Which words are \"a treasure of Paradise\"?", "bn": "কোন বাক্য \"জান্নাতের ধনভাণ্ডার\"?"}', '{"en": "\"There is no might nor power except with Allah.\"", "bn": "\"আল্লাহ ছাড়া কোনো শক্তি ও সামর্থ্য নেই।\""}', 'Sahih al-Bukhari 6384', 3) ON CONFLICT (id) DO NOTHING;
