INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('ba257e5f-55c2-5a2a-b743-7c06d72c6c0c', 'f13c3417-7533-5e57-81f4-85dd9bbd88b6', '{"en": "What is the \"master of seeking forgiveness\" called?", "bn": "\"ক্ষমা চাওয়ার সর্দার\" দোয়াকে কী বলে?"}', '{"en": "\"O Allah, You are my Lord, there is no god but You…\"", "bn": "\"হে আল্লাহ, আপনি আমার রব, আপনি ছাড়া কোনো উপাস্য নেই…\""}', 'Sahih al-Bukhari 6306', 4) ON CONFLICT (id) DO NOTHING;
