INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('2075f470-701f-553b-9527-c3369cc70787', 'f13c3417-7533-5e57-81f4-85dd9bbd88b6', '{"en": "Reciting Ayat al-Kursi before sleeping keeps you protected until…?", "bn": "ঘুমানোর আগে আয়াতুল কুরসি পড়লে কখন পর্যন্ত সুরক্ষিত থাকবেন?"}', '{"en": "A guardian from Allah stays with you and no devil comes near until morning.", "bn": "আল্লাহর পক্ষ থেকে একজন রক্ষাকারী থাকে এবং সকাল পর্যন্ত শয়তান কাছে আসে না।"}', 'Sahih al-Bukhari 2311', 6) ON CONFLICT (id) DO NOTHING;
