INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('97a5fd13-ec86-5049-b622-13e47ef5ec85', 'f13c3417-7533-5e57-81f4-85dd9bbd88b6', '{"en": "Which two surahs are the best for seeking refuge?", "bn": "আশ্রয় চাওয়ার জন্য কোন দুটি সূরা সর্বোত্তম?"}', '{"en": "\"Have you not seen ayahs revealed tonight, the like of which were never seen: al-Falaq and an-Nas.\"", "bn": "\"তুমি কি দেখোনি আজ রাতে এমন আয়াত নাজিল হয়েছে, যার মতো কখনো দেখা যায়নি: আল-ফালাক ও আন-নাস।\""}', 'Sahih Muslim 814', 7) ON CONFLICT (id) DO NOTHING;
