INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('5c09ba75-8a71-557f-96bb-686fd9c3c311', 'f13c3417-7533-5e57-81f4-85dd9bbd88b6', '{"en": "The dua of Yunus begins with…?", "bn": "ইউনুস (আ.)-এর দোয়া শুরু হয়…?"}', '{"en": "\"…I have indeed been among the wrongdoers.\"", "bn": "\"…নিশ্চয়ই আমি জালিমদের অন্তর্ভুক্ত ছিলাম।\""}', 'Quran 21:87', 8) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('fdd0b7b1-b531-5844-a2a3-d2354f0406fb', '5c09ba75-8a71-557f-96bb-686fd9c3c311', '{"en": "La ilaha illa anta, subhanaka", "bn": "লা ইলাহা ইল্লা আনতা, সুবহানাকা"}', true, 1), ('76e40140-5876-512d-b5e6-c16e202b66c7', '5c09ba75-8a71-557f-96bb-686fd9c3c311', '{"en": "Rabbana atina", "bn": "রব্বানা আতিনা"}', false, 2), ('ef2123c7-574e-5126-bc52-1b58866271ae', '5c09ba75-8a71-557f-96bb-686fd9c3c311', '{"en": "Bismillah", "bn": "বিসমিল্লাহ"}', false, 3), ('510e0d2e-b46c-53e7-b1c7-0095a5d3d04b', '5c09ba75-8a71-557f-96bb-686fd9c3c311', '{"en": "Allahumma barik", "bn": "আল্লাহুম্মা বারিক"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('2bbc4f0e-3e73-5d1e-8a7b-953e98468a1f', 'f13c3417-7533-5e57-81f4-85dd9bbd88b6', '{"en": "Dua between the adhan and the iqamah is…?", "bn": "আজান ও ইকামতের মাঝের দোয়া…?"}', '{"en": "\"Dua between the adhan and the iqamah is not rejected.\"", "bn": "\"আজান ও ইকামতের মাঝের দোয়া ফিরিয়ে দেওয়া হয় না।\""}', 'Jami‘ at-Tirmidhi 212', 9) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('81f87d4a-e885-5333-b86d-b7e974d46582', '2bbc4f0e-3e73-5d1e-8a7b-953e98468a1f', '{"en": "Not rejected", "bn": "ফিরিয়ে দেওয়া হয় না"}', true, 1), ('924fffb3-176e-5bee-80d0-8a9287c90437', '2bbc4f0e-3e73-5d1e-8a7b-953e98468a1f', '{"en": "Forbidden", "bn": "নিষিদ্ধ"}', false, 2), ('1a57d1a3-dd23-5e7f-80fb-552bffafa000', '2bbc4f0e-3e73-5d1e-8a7b-953e98468a1f', '{"en": "Disliked", "bn": "অপছন্দনীয়"}', false, 3), ('e8640ed7-4f89-5a6b-a26d-ef07e202a9af', '2bbc4f0e-3e73-5d1e-8a7b-953e98468a1f', '{"en": "Only for imams", "bn": "শুধু ইমামের জন্য"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('a900bfe1-e404-5abc-ac53-7b16cb76108b', 'f13c3417-7533-5e57-81f4-85dd9bbd88b6', '{"en": "What should you say when leaving home?", "bn": "ঘর থেকে বের হওয়ার সময় কী বলবেন?"}', '{"en": "\"…there is no might nor power except with Allah.\" It is said to him: you are guided, sufficed and protected.", "bn": "\"…আল্লাহ ছাড়া কোনো শক্তি ও সামর্থ্য নেই।\" তাকে বলা হয়: তুমি হেদায়াত পেলে, যথেষ্ট হলে ও রক্ষা পেলে।"}', 'Sunan Abi Dawud 5095', 10) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('cd9768ce-a519-5614-868b-1dcacd4b2f04', 'a900bfe1-e404-5abc-ac53-7b16cb76108b', '{"en": "Bismillah, tawakkaltu ‘alallah…", "bn": "বিসমিল্লাহি, তাওয়াক্কালতু আলাল্লাহ…"}', true, 1), ('191422f5-4fc5-5a51-ac89-030b03e1428b', 'a900bfe1-e404-5abc-ac53-7b16cb76108b', '{"en": "Alhamdulillah only", "bn": "শুধু আলহামদুলিল্লাহ"}', false, 2), ('9cf849f9-7eae-54fb-bd3d-3642e10c78c0', 'a900bfe1-e404-5abc-ac53-7b16cb76108b', '{"en": "Nothing", "bn": "কিছু না"}', false, 3), ('d971c6a6-10c3-5e74-a58a-0066c6857130', 'a900bfe1-e404-5abc-ac53-7b16cb76108b', '{"en": "Ameen", "bn": "আমিন"}', false, 4) ON CONFLICT (id) DO NOTHING;
